/**
 * Detect active panel scroll (mobile inertial momentum + desktop wheel/drag).
 * Pauses reactive UI updates until scroll fully settles.
 */

import { MODAL_OPEN_SELECTOR } from '../ui/breakpoints.ts';

const PANEL_SELECTOR = '.combat-area, .team-area, .secondary-content';
const SCROLLABLE_SELECTOR = `${PANEL_SELECTOR}, #storageList, .tab-content.active`;
const SCROLL_END_DELAY_MS = 400;

let initialized = false;
let scrolling = false;
let touchActive = false;
let pointerActive = false;
const boundPanels = new WeakSet<HTMLElement>();
let scrollEndTimer: ReturnType<typeof setTimeout> | null = null;
const scrollTops = new WeakMap<HTMLElement, number>();
const scrollEndCallbacks = new Set<() => void>();
const deferredApplies = new Map<string, () => void>();

/** Heavier store applies run on later frames so scroll stays responsive. */
const DEFERRED_APPLY_PRIORITY = [
    'teamCombatMeta',
    'teamHeader',
    'team',
    'quests',
    'storage',
] as const;

function flushScrollEndCallbacks(): void {
    flushDeferredApplies();
    for (const cb of scrollEndCallbacks) {
        try {
            cb();
        } catch {
            /* subscriber error */
        }
    }
}

function maybeFinishScrollSession(): void {
    if (touchActive || pointerActive || scrolling) return;
    flushScrollEndCallbacks();
}

function markScrolling(): void {
    if (!scrolling) scrolling = true;
    if (scrollEndTimer != null) clearTimeout(scrollEndTimer);
    scrollEndTimer = setTimeout(finishScrolling, SCROLL_END_DELAY_MS);
}

function finishScrolling(): void {
    scrollEndTimer = null;
    scrolling = false;
    maybeFinishScrollSession();
}

function flushDeferredApplies(): void {
    if (!deferredApplies.size) return;

    const ordered: Array<() => void> = [];
    for (const key of DEFERRED_APPLY_PRIORITY) {
        const fn = deferredApplies.get(key);
        if (fn) {
            ordered.push(fn);
            deferredApplies.delete(key);
        }
    }
    for (const fn of deferredApplies.values()) ordered.push(fn);
    deferredApplies.clear();

    if (ordered.length <= 1) {
        ordered[0]?.();
        return;
    }

    let index = 0;
    const runNext = (): void => {
        if (index >= ordered.length) return;
        ordered[index]?.();
        index += 1;
        if (index < ordered.length) requestAnimationFrame(runNext);
    };
    runNext();
}

function isScrollablePanelTarget(target: EventTarget | null): boolean {
    if (!(target instanceof Element)) return false;
    return !!target.closest(SCROLLABLE_SELECTOR);
}

function onPanelScroll(ev: Event): void {
    const el = ev.currentTarget;
    if (!(el instanceof HTMLElement)) return;

    scrollTops.set(el, el.scrollTop);
    markScrolling();
}

function onPanelWheel(): void {
    markScrolling();
}

function isModalOpen(): boolean {
    return typeof document !== 'undefined' && !!document.querySelector(MODAL_OPEN_SELECTOR);
}

function onTouchStart(ev: TouchEvent): void {
    if (!isScrollablePanelTarget(ev.target)) return;
    touchActive = true;
    markScrolling();
}

function onTouchEnd(): void {
    touchActive = false;
    maybeFinishScrollSession();
}

function onPointerDown(ev: PointerEvent): void {
    if (!isScrollablePanelTarget(ev.target)) return;
    pointerActive = true;
    markScrolling();
}

function onPointerUp(): void {
    if (!pointerActive) return;
    pointerActive = false;
    maybeFinishScrollSession();
}

function bindPanel(el: HTMLElement): void {
    if (boundPanels.has(el)) return;
    boundPanels.add(el);
    scrollTops.set(el, el.scrollTop);
    el.addEventListener('scroll', onPanelScroll, { passive: true });
    el.addEventListener('wheel', onPanelWheel, { passive: true });
    if ('onscrollend' in el) {
        el.addEventListener('scrollend', () => {
            if (scrollEndTimer != null) clearTimeout(scrollEndTimer);
            finishScrolling();
        }, { passive: true });
    }
}

function bindPanels(): void {
    document.querySelectorAll(PANEL_SELECTOR).forEach((el) => {
        if (el instanceof HTMLElement) bindPanel(el);
    });
    document.querySelectorAll('.secondary-content > .tab-content').forEach((el) => {
        if (el instanceof HTMLElement) bindPanel(el);
    });
    document.querySelectorAll('#boutiqueTab .shop-subtab-scroll').forEach((el) => {
        if (el instanceof HTMLElement) bindPanel(el);
    });
}

/** Call once at boot and on mobile layout init. */
export function initMobileScrollGate(): void {
    if (typeof document === 'undefined') return;
    if (!initialized) {
        initialized = true;
        document.addEventListener('touchstart', onTouchStart, { passive: true, capture: true });
        document.addEventListener('touchend', onTouchEnd, { passive: true, capture: true });
        document.addEventListener('touchcancel', onTouchEnd, { passive: true, capture: true });
        document.addEventListener('pointerdown', onPointerDown, { passive: true, capture: true });
        document.addEventListener('pointerup', onPointerUp, { passive: true, capture: true });
        document.addEventListener('pointercancel', onPointerUp, { passive: true, capture: true });
    }
    bindPanels();
}

export function isMobilePanelScrolling(): boolean {
    return scrolling || touchActive || pointerActive;
}

/** Register callback fired once when panel scroll settles (incl. inertial). */
export function onMobileScrollEnd(cb: () => void): () => void {
    scrollEndCallbacks.add(cb);
    return () => scrollEndCallbacks.delete(cb);
}

/**
 * Defer a store apply while a panel is scrolling.
 * Coalesces multiple calls with the same key to the latest applyFn.
 */
export function deferIfMobileScrolling(key: string, applyFn: () => void): void {
    if (!isMobilePanelScrolling() || isModalOpen()) {
        applyFn();
        return;
    }
    deferredApplies.set(key, applyFn);
}

/** @internal Vitest only */
export function resetMobileScrollGateForTests(): void {
    scrolling = false;
    touchActive = false;
    pointerActive = false;
    if (scrollEndTimer != null) {
        clearTimeout(scrollEndTimer);
        scrollEndTimer = null;
    }
    deferredApplies.clear();
    scrollEndCallbacks.clear();
    initialized = false;
}

/** @internal Vitest only */
export function _markMobileScrollingForTests(): void {
    markScrolling();
}

/** @internal Vitest only */
export function _setTouchActiveForTests(active: boolean): void {
    touchActive = active;
}

/** @internal Vitest only */
export function _setPointerActiveForTests(active: boolean): void {
    pointerActive = active;
}

/** @internal Vitest only */
export function _finishMobileScrollingForTests(): void {
    if (scrollEndTimer != null) {
        clearTimeout(scrollEndTimer);
        scrollEndTimer = null;
    }
    finishScrolling();
}
