/**
 * Preserve scroll position on main UI panels when Svelte/store updates re-render content.
 */

import { isMobilePanelScrolling, onMobileScrollEnd } from './mobileScrollGate.ts';

const SCROLL_ROOT_SELECTORS = [
    '.combat-area',
    '.team-area',
    '.secondary-content',
    '#secondaryContent .tab-content.active',
    '#boutiqueTab .shop-subtab-scroll',
    '#storageList',
] as const;

let pendingRestore: Map<HTMLElement, number> | null = null;

function applyScrollRestore(saved: Map<HTMLElement, number>): void {
    requestAnimationFrame(() => {
        requestAnimationFrame(() => {
            saved.forEach((top, el) => {
                if (!el.isConnected) return;
                const max = Math.max(0, el.scrollHeight - el.clientHeight);
                el.scrollTop = Math.min(top, max);
            });
        });
    });
}

export function captureUiScrollPositions(): Map<HTMLElement, number> {
    const map = new Map<HTMLElement, number>();
    for (const sel of SCROLL_ROOT_SELECTORS) {
        document.querySelectorAll(sel).forEach((el) => {
            if (!(el instanceof HTMLElement)) return;
            if (el.scrollHeight > el.clientHeight + 1) {
                map.set(el, el.scrollTop);
            }
        });
    }
    return map;
}

export function restoreUiScrollPositions(saved: Map<HTMLElement, number>): void {
    if (!saved.size) return;

    if (isMobilePanelScrolling()) {
        pendingRestore = saved;
        return;
    }

    applyScrollRestore(saved);
}

onMobileScrollEnd(() => {
    // Captures taken mid-scroll are stale once the user has settled elsewhere.
    pendingRestore = null;
});

export function withUiScrollPreserve(run: () => void): void {
    const saved = captureUiScrollPositions();
    run();
    restoreUiScrollPositions(saved);
}

/** True if element is visible enough to scroll into view without jumping hidden panels. */
export function isElementVisibleForScroll(el: HTMLElement): boolean {
    if (!el.isConnected) return false;
    const style = getComputedStyle(el);
    if (style.display === 'none' || style.visibility === 'hidden') return false;
    const rect = el.getBoundingClientRect();
    if (rect.width <= 0 && rect.height <= 0) return false;

    const teamArea = document.querySelector('.team-area');
    const extras = document.getElementById('secondaryContent');
    if (teamArea instanceof HTMLElement && teamArea.contains(el)) {
        if (getComputedStyle(teamArea).display === 'none') return false;
        if (!teamArea.classList.contains('mobile-active') && teamArea.closest('.game-container')) {
            const mobile = window.matchMedia?.('(max-width: 1200px)').matches;
            if (mobile && !teamArea.classList.contains('mobile-active')) return false;
        }
    }
    if (extras instanceof HTMLElement && extras.contains(el)) {
        if (getComputedStyle(extras).display === 'none') return false;
        if (!extras.classList.contains('mobile-active')) {
            const mobile = window.matchMedia?.('(max-width: 1200px)').matches;
            if (mobile && !extras.classList.contains('mobile-active')) return false;
        }
        const tab = el.closest('.tab-content');
        if (tab instanceof HTMLElement && tab.hidden) return false;
    }
    return true;
}
